import pandas as pd

def popularity_percentage(friends: pd.DataFrame) -> pd.DataFrame:
    df1 = friends[['user1', 'user2']]
    df2 = friends[['user2', 'user1']].rename(columns={'user2': 'user1', 'user1': 'user2'})
    all_pairs = pd.concat([df1, df2]).drop_duplicates()
    total_users = all_pairs['user1'].nunique()
    if total_users == 0:
        return pd.DataFrame(columns=['user1', 'percentage_popularity'])
    grouped = all_pairs.groupby('user1').size().reset_index(name='friends_count')
    grouped['percentage_popularity'] = (grouped['friends_count'] * 100.0 / total_users).round(2)
    return grouped[['user1', 'percentage_popularity']].sort_values(by='user1')
